import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.rZZZX73S.js";var c=JSON.parse(`{"title":"Waypoints","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/waypoints/docs/index.md"},"headers":[],"relativePath":"packages/waypoints/docs/index.md","filePath":"packages/waypoints/docs/index.md","lastUpdated":1791729378000}`),l={name:`packages/waypoints/docs/index.md`},u={id:`waypoints`,tabindex:`-1`,class:`component-page-title`},d={class:`component-page-title__version`,href:`https://github.com/filiphsps/pumpkin-plugins/releases/tag/waypoints-v0.0.4`,"aria-label":`Release v0.0.4`};function f(i,c,l,f,p,m){let h=s(`Badge`);return e(),o(`div`,null,[n(`h1`,u,[c[0]||=n(`img`,{class:`component-page-title__icon`,src:`/pumpkin-plugins/packages/waypoints/icon.svg`,alt:``,"aria-hidden":`true`,width:`48`,height:`48`},null,-1),c[1]||=n(`span`,{class:`component-page-title__text`},[t(`Waypoints `),n(`a`,{class:`header-anchor`,href:`#waypoints`,"aria-label":`Permalink to “Waypoints”`},`​`)],-1),n(`a`,d,[a(h,{type:`info`,text:`v0.0.4`})])]),c[2]||=r(`<p>Waypoints stores shared named locations on the server. Each waypoint can have a display label, description, color, item icon, and optional HUD visibility range. Waypoints are restricted by default; operators can make them public or grant access to specific players, permission nodes, or permission-marker groups. Players can find and teleport to enabled waypoints they can access. Records have no creator ownership.</p><p>Install <code>waypoints.wasm</code> in the Pumpkin server&#39;s <code>plugins/</code> directory and restart. The plugin has no config file. It stores versioned records in <code>plugins/data/Waypoints/waypoints.json</code> and keeps a byte-identical <code>waypoints.v1.json</code> backup when migrating the previous schema.</p><h2 id="create-and-use-waypoints" tabindex="-1">Create and use waypoints <a class="header-anchor" href="#create-and-use-waypoints" aria-label="Permalink to “Create and use waypoints”">​</a></h2><p>Operators can create a waypoint at their exact position with <code>/wp create &quot;Home Base&quot;</code>, or provide absolute coordinates with <code>/wp create &quot;Home Base&quot; 120.5 64 -30</code>. Names are unique across all dimensions. Use <code>/wp list</code> to see enabled waypoints you can access, <code>/wp info &lt;name&gt;</code> for details, and <code>/wp tp &lt;name&gt;</code> to teleport yourself. Operators can use <code>/wp tp &lt;name&gt; @a</code> to teleport a player selector.</p><p>Only server operators can create, edit, enable, disable, grant, or delete waypoints. Every administrative handler checks Pumpkin&#39;s operator list even if a command permission was manually granted. Player grants resolve online names and store UUIDs. A group grant checks the permission marker <code>Waypoints:group.&lt;slug&gt;</code>; another permission provider must assign that marker to group members.</p><h2 id="java-waypoint-hud" tabindex="-1">Java waypoint HUD <a class="header-anchor" href="#java-waypoint-hud" aria-label="Permalink to “Java waypoint HUD”">​</a></h2><p>Minecraft Java 26.3 players see each enabled waypoint they can access in the same dimension and within its optional visibility range. Private display packets keep restricted names and personalized distances off other clients. Names reveal after a settled look and stay visible near the destination; distant peripheral markers show just their distance and icon. Labels use the waypoint color, a shadow, and a subtle backdrop independent of world lighting. Iconless waypoints use a colored diamond.</p><p>The HUD uses client-only TextDisplay entities along each waypoint&#39;s world direction. A smooth depth curve approaches a maximum of 24 blocks from the player&#39;s eyes, reducing the apparent movement caused by delayed position samples. Labels face the viewer and render through terrain. Camera rotation does not move or replace them. Between sixteen and three blocks from a waypoint, the projection blends into a world anchor two blocks above its stored Y coordinate. It never passes the destination during the blend; within three blocks it stays at the anchor. The transition works in both directions.</p><p>Perspective sizing uses camera-forward depth to avoid enlarging labels at the screen edges, and keeps their apparent size consistent through the approach at a fixed field of view. Labels are limited to 32 characters on the HUD; <code>/wp info</code> retains the complete text. Distances use meters below one kilometer and tenths of kilometers above it, with hysteresis to prevent rounding flicker. Text, icons, and backdrop fade between two and 0.75 blocks from the destination, leaving the immediate view clear.</p><p>Waypoints stored in the same half-block grid cell get a stable vertical stack, ordered by identifier, without camera-dependent rearrangement. Distinct waypoints along the same bearing may still overlap. Steps and jumps receive strong elevation damping while steep vertical destinations respond faster. Damping eases off near the world anchor. Position and scale updates interpolate over one client tick; unchanged text is not resent for appearance-only updates.</p><p>This approximates a first-person HUD: network latency, client view bobbing, and third-person camera offsets can still affect alignment. The server cannot read client FOV or reliably detect Java item-use state, so spyglass and modded zoom enlarge the labels. Other Java protocol versions do not receive the HUD. Bedrock support depends on the Pumpkin API and will be added when the API makes it possible. Icons use vanilla 26.3 atlas textures; block items use a representative model texture, and custom item IDs require the corresponding <code>item/&lt;path&gt;</code> sprite in the client&#39;s resource pack.</p><p>Malformed or unsupported storage is preserved and disables writes. Fix the file before expecting changes to persist.</p>`,12)])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};